import type { FC } from 'react';
import { motion } from 'framer-motion';
import { tools, TOOL_CATEGORIES } from '@/data/tools';
import ToolCard from '@/components/tools/ToolCard';

const ToolsIndex: FC = () => {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="pt-24"
    >
      <section className="section-container pb-12 md:pb-16">
        <div className="text-center mb-8 md:mb-12">
          <h1 className="text-2xl md:text-3xl font-display font-medium mb-6 text-accent">
            Tools
          </h1>
          <p className="text-muted-foreground max-w-2xl mx-auto text-xl font-light leading-relaxed">
            free, no-signup utilities — built for anyone to use
          </p>
        </div>

        <div className="max-w-6xl mx-auto space-y-12">
          {TOOL_CATEGORIES.map((category) => {
            const categoryTools = tools.filter((tool) => tool.category === category.id);
            if (categoryTools.length === 0) return null;

            return (
              <div key={category.id}>
                <h2 className="text-sm font-medium text-muted-foreground uppercase tracking-widest mb-4">
                  {category.label}
                </h2>
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-4">
                  {categoryTools.map((tool, index) => (
                    <ToolCard key={tool.slug} tool={tool} index={index} />
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </section>
    </motion.div>
  );
};

export default ToolsIndex;
